const input = $json.body ?? $json;

if (input.approved !== true) {
  throw new Error('Kirana Kavach action was not approved.');
}

const merchantId = input.merchant_id;
const action = input.action ?? {};
const actionType = action.type;
const payload = action.payload ?? {};
const now = new Date().toISOString();

if (!merchantId || !actionType) {
  throw new Error('merchant_id and action.type are required.');
}

if (actionType === 'CREATE_PAYTM_SUPPORT_CASE') {
  const ids = payload.transaction_ids ?? [];
  const amount = Number(payload.pending_amount ?? 0);

  return [{
    json: {
      use_twilio: false,
      response: {
        merchant_id: merchantId,
        action_type: actionType,
        status: 'executed',
        external_id: `KK-SUPPORT-DEMO-${Date.now()}`,
        outcome_note: `Demo Paytm support case prepared for ${ids.length} transaction(s) totaling ₹${amount.toFixed(0)}.`,
        executed_at: now,
        provider: 'n8n',
        confirmation_source: input.confirmation_source ?? 'unknown'
      }
    }
  }];
}

if (actionType === 'DRAFT_CUSTOMER_MESSAGE') {
  const message = String(payload.message ?? '').trim();
  const customerId = String(payload.customer_id ?? '').trim();

  if (!message) {
    throw new Error('Customer message draft is missing.');
  }

  if (!customerId) {
    throw new Error('Customer ID is missing.');
  }

  const twilioTo = String(payload.twilio_whatsapp_to ?? '').trim();
  const twilioFrom = String(payload.twilio_whatsapp_from ?? '').trim();
  const twilioAccountSid = String(payload.twilio_account_sid ?? '').trim();
  const twilioContentSid = String(payload.twilio_content_sid ?? '').trim();

  if (twilioTo && twilioFrom && twilioAccountSid && twilioContentSid) {
    return [{
      json: {
        use_twilio: true,
        merchant_id: merchantId,
        customer_id: customerId,
        message: message,
        confirmation_source: input.confirmation_source ?? 'unknown',
        twilio_whatsapp_to: twilioTo,
        twilio_whatsapp_from: twilioFrom,
        twilio_account_sid: twilioAccountSid,
        twilio_content_sid: twilioContentSid
      }
    }];
  }

  const campaignId = `KK-REACT-DEMO-${Date.now()}`;
  const paymentLinkReference = `KK-PAY-DEMO-${Date.now()}`;

  return [{
    json: {
      use_twilio: false,
      response: {
        merchant_id: merchantId,
        action_type: actionType,
        status: 'prepared',
        external_id: campaignId,
        campaign_type: 'customer_reactivation',
        customer_id: customerId,
        message: message,
        payment_link_reference: paymentLinkReference,
        outcome_note: 'Customer reactivation pack prepared for merchant review; no customer message was sent automatically.',
        executed_at: now,
        provider: 'n8n',
        confirmation_source: input.confirmation_source ?? 'unknown'
      }
    }
  }];
}

throw new Error(`Unsupported action type: ${actionType}`);

const twilioRes = $json;
const req = $('Validate and Prepare Action').first().json;
const now = new Date().toISOString();

function maskPhone(phone) {
  if (!phone) return 'unknown';
  const str = String(phone).trim();
  if (str.length <= 6) return str;
  return str.slice(0, 5) + '******' + str.slice(-4);
}

if (twilioRes.sid) {
  return [{
    json: {
      response: {
        merchant_id: req.merchant_id,
        action_type: 'DRAFT_CUSTOMER_MESSAGE',
        status: twilioRes.status || 'queued',
        channel: 'whatsapp',
        provider: 'twilio',
        message_sid: twilioRes.sid,
        external_id: twilioRes.sid,
        customer_id: req.customer_id,
        campaign_type: 'customer_reactivation',
        recipient: maskPhone(req.twilio_whatsapp_to),
        template_sid: req.twilio_content_sid,
        draft_message: req.message,
        payment_link_reference: `KK-PAY-DEMO-${Date.now()}`,
        outcome_note: 'WhatsApp message submitted to Twilio using the configured trial template.',
        executed_at: now,
        confirmation_source: req.confirmation_source
      }
    }
  }];
}

return [{
  json: {
    response: {
      merchant_id: req.merchant_id,
      action_type: 'DRAFT_CUSTOMER_MESSAGE',
      status: 'failed',
      channel: 'whatsapp',
      provider: 'twilio',
      error_code: twilioRes.code || (twilioRes.status ? String(twilioRes.status) : '500'),
      outcome_note: `Twilio error: ${twilioRes.message || twilioRes.detail || 'Request failed'}`,
      executed_at: now,
      confirmation_source: req.confirmation_source
    }
  }
}];
